-- | The module GHC keeps the primitive operations in, which has no
-- interface file, and the fixities declared there.
primops :: (Text, [(Text, Fixity)])
primops =
  ( "GHC.Internal.Prim",
    [ ("*#", Fixity LeftAssoc 7),
      ("*##", Fixity LeftAssoc 7),
      ("**##", Fixity LeftAssoc 9),
      ("+#", Fixity LeftAssoc 6),
      ("+##", Fixity LeftAssoc 6),
      ("-#", Fixity LeftAssoc 6),
      ("-##", Fixity LeftAssoc 6),
      ("/##", Fixity LeftAssoc 7),
      ("/=#", Fixity NoAssoc 4),
      ("/=##", Fixity NoAssoc 4),
      ("<#", Fixity NoAssoc 4),
      ("<##", Fixity NoAssoc 4),
      ("<=#", Fixity NoAssoc 4),
      ("<=##", Fixity NoAssoc 4),
      ("==#", Fixity NoAssoc 4),
      ("==##", Fixity NoAssoc 4),
      (">#", Fixity NoAssoc 4),
      (">##", Fixity NoAssoc 4),
      (">=#", Fixity NoAssoc 4),
      (">=##", Fixity NoAssoc 4),
      ("seq", Fixity RightAssoc 0)
    ]
  )
